rows.json_content:
[
  {
    "title": "Before You Build",
    "content": "- Define your goal: what should this website DO? (Get calls, book jobs, sell products)\n- Know your customer: who are you trying to reach, and what are they searching for?\n- Claim your Google Business Profile and verify it — this is step one for local SEO\n- Choose a domain that's short, brandable, and matches your business name\n- Decide on hosting and who owns the domain — you should always own both"
  },
  {
    "title": "Content You'll Need",
    "content": "- Clear, honest copy that speaks to your customer's problem\n- Real photos of your work — not stock photos\n- Your exact service area and the neighborhoods you serve\n- Contact info that's identical everywhere: website, Google, directories\n- Reviews: gather at least 5 before you launch, and keep collecting"
  },
  {
    "title": "Design That Converts",
    "content": "- One clear call-to-action above the fold: Call Now, Book Now, or Get a Quote\n- Mobile-first: most local searches happen on phones\n- Click-to-call button visible at all times on mobile\n- Fast loading — every second of delay costs you visitors\n- Trust signals: licenses, credentials, before/after photos, testimonials"
  },
  {
    "title": "Before You Go Live",
    "content": "- Test the site on real phones, not just desktop\n- Check every link and form\n- Set up Google Analytics and Google Search Console\n- Add local schema markup so Google understands your business\n- Write a privacy policy and terms page"
  },
  {
    "title": "After Launch",
    "content": "- Submit your site to Google Search Console and request indexing\n- Keep your Google Business Profile updated with new photos and posts\n- Ask every happy customer for a review\n- Track which pages get traffic and which pages get calls\n- Plan regular updates — a website is an asset, not a one-time expense"
  }
]
